import React, { useEffect, useRef, useState } from "react";
import "./Ge.css";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: 50,
    scanlines: 50,
    saturation: 50,
    pixelation: 50,
  });
  const [timestamp, setTimestamp] = useState(new Date());
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);
  const animationRef = useRef();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  const generateGrain = (ctx, width, height, intensity = 300, gamma = 1.4) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    const intensityMultiplier = effects.grain / 50;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity * intensityMultiplier) - (intensity * intensityMultiplier) / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 3, alpha = 0.15) => {
    ctx.save();
    const alphaMultiplier = effects.scanlines / 50;
    ctx.fillStyle = `rgba(0,0,0,${alpha * alphaMultiplier})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applySaturation = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const saturationMultiplier = effects.saturation / 50;

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const gray = 0.2989 * r + 0.5870 * g + 0.1140 * b;

      data[i] = gray + (r - gray) * saturationMultiplier;
      data[i + 1] = gray + (g - gray) * saturationMultiplier;
      data[i + 2] = gray + (b - gray) * saturationMultiplier;
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const applyPixelation = (ctx, width, height) => {
    const pixelSize = Math.max(1, Math.floor(20 * (1 - effects.pixelation / 100)));
    const imageData = ctx.getImageData(0, 0, width, height);
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = width;
    tempCanvas.height = height;
    const tempCtx = tempCanvas.getContext('2d');
    tempCtx.putImageData(imageData, 0, 0);

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(
      tempCanvas,
      0, 0, width, height,
      0, 0, width / pixelSize, height / pixelSize
    );
    ctx.drawImage(
      canvasRef.current,
      0, 0, width / pixelSize, height / pixelSize,
      0, 0, width, height
    );
    ctx.imageSmoothingEnabled = true;
  };

  const thresholdImage = (canvas) => {
    const ctx = canvas.getContext("2d");
    const imageData = ctx.getImageData(0, 0, 1080, 1080);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const avg = (data[i] + data[i + 1] + data[i + 2]) / 3;
      const val = avg > 128 ? 255 : 0;
      data[i] = data[i + 1] = data[i + 2] = val;
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
  };

  const generateImage = (imagePaths) => {
    setTimestamp(new Date());
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const TILE_SIZE = 36;
    const GRID = 30;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    const getShuffledIndices = () => {
      const indices = Array.from({ length: GRID * GRID }, (_, i) => i);
      for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
      }
      return indices;
    };

    const sliceAndShuffle = (img) => {
      const tempCanvas = document.createElement("canvas");
      tempCanvas.width = 1080;
      tempCanvas.height = 1080;
      const tempCtx = tempCanvas.getContext("2d");
      tempCtx.drawImage(img, 0, 0, 1080, 1080);

      const tiles = [];
      for (let y = 0; y < GRID; y++) {
        for (let x = 0; x < GRID; x++) {
          tiles.push(tempCtx.getImageData(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE));
        }
      }

      const shuffledIndices = getShuffledIndices();
      const shuffledCanvas = document.createElement("canvas");
      shuffledCanvas.width = 1080;
      shuffledCanvas.height = 1080;
      const shuffledCtx = shuffledCanvas.getContext("2d");

      shuffledIndices.forEach((toIdx, fromIdx) => {
        const x = (toIdx % GRID) * TILE_SIZE;
        const y = Math.floor(toIdx / GRID) * TILE_SIZE;
        shuffledCtx.putImageData(tiles[fromIdx], x, y);
      });

      return shuffledCanvas;
    };

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      const shuffledOddCanvas = document.createElement("canvas");
      shuffledOddCanvas.width = 1080;
      shuffledOddCanvas.height = 1080;
      const shuffledOddCtx = shuffledOddCanvas.getContext("2d");

      [0, 2, 4].forEach((i) => {
        if (images[i]) {
          const shuffled = sliceAndShuffle(images[i]);
          shuffledOddCtx.drawImage(shuffled, 0, 0);
        }
      });

      ctx.drawImage(shuffledOddCanvas, 0, 0);

      [1, 3].forEach((i) => {
        if (images[i]) {
          const shuffled = sliceAndShuffle(images[i]);
          const bwCanvas = thresholdImage(shuffled);
          const bwCtx = bwCanvas.getContext("2d");
          const bwData = bwCtx.getImageData(0, 0, 1080, 1080).data;
          const baseData = ctx.getImageData(0, 0, 1080, 1080);

          for (let j = 0; j < baseData.data.length; j += 4) {
            const alpha = bwData[j] / 255;
            baseData.data[j + 3] *= alpha;
          }
          ctx.putImageData(baseData, 0, 0);
        }
      });

      if (effects.grain) generateGrain(ctx, canvas.width, canvas.height);
      if (effects.scanlines) applyScanlines(ctx, canvas.width, canvas.height);
      if (effects.saturation) applySaturation(ctx, canvas.width, canvas.height);
      if (effects.pixelation) applyPixelation(ctx, canvas.width, canvas.height);
    });
  };

  const handleEffectChange = (effect, value) => {
    setEffects(prev => ({ ...prev, [effect]: value }));
    generateImage(imagePaths);
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  return (
    <div ref={containerRef} className="ge-container">
      <div className="ge-control-panel">
        <div className="ge-control-group">
          <label className="ge-control-label">Grain: {effects.grain}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.grain}
            onChange={(e) => handleEffectChange('grain', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Scanlines: {effects.scanlines}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.scanlines}
            onChange={(e) => handleEffectChange('scanlines', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Saturation: {effects.saturation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.saturation}
            onChange={(e) => handleEffectChange('saturation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Pixelation: {effects.pixelation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.pixelation}
            onChange={(e) => handleEffectChange('pixelation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
      </div>

      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        className="ge-canvas"
        style={{ opacity: isFading ? 0.2 : 1 }}
      />

      <div className="ge-timestamp">
        {timestamp.toLocaleString()}
      </div>

      <div className="ge-button-container">
        <button
          onClick={handleRegenerate}
          className="ge-button ge-button-regenerate"
        >
          Regenerate
        </button>
        <button
          onClick={handleDownload}
          className="ge-button ge-button-download"
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
